ENGINE = """// Solar Create Menu - generated by Solar Settings. Do not edit here: change Solar Settings > Create Buttons.
(function () {
    const DT = "__DT__";
    const MARK = "\\u2060"; // invisible mark so buttons added here are never hidden by mistake
    const BASE = ["customer", "custom_lead", "company", "project", "capacity_kw", "system_type",
        "district", "village_city", "mobile_number", "email", "site_address"];

    function passes(frm, st) {
        if (st.show_when === "After Submit") return frm.doc.docstatus === 1;
        if (st.show_when === "Field has value") {
            const raw = frm.doc[st.when_field];
            const v = String(raw == null ? "" : raw).trim().toLowerCase();
            return (st.when_value || "").split(",").map(x => x.trim().toLowerCase()).filter(Boolean).includes(v);
        }
        return frm.doc.docstatus !== 2;
    }

    function back_link(st, src) {
        if (st.link_field) return st.link_field;
        const f = (frappe.get_meta(st.creates).fields || []).find(df => df.fieldtype === "Link" && df.options === src);
        return f ? f.fieldname : null;
    }

    async function existing(frm, st, lf) {
        let filters = null;
        if (lf) {
            filters = {};
            filters[lf] = frm.doc.name;
        } else if (frm.doc.customer && frappe.meta.has_field(st.creates, "customer")) {
            filters = { customer: frm.doc.customer };
            if (frm.doc.project && frappe.meta.has_field(st.creates, "project")) filters.project = frm.doc.project;
        }
        if (!filters) return null;
        const r = await frappe.db.get_list(st.creates, { filters: filters, fields: ["name"], order_by: "creation desc", limit: 1 });
        return r.length ? r[0].name : null;
    }

    function create(frm, st, lf) {
        if (frm.is_dirty()) { frappe.msgprint(__("Please save first.")); return; }
        const names = BASE.concat((st.copy_fields || "").split(",").map(x => x.trim()).filter(Boolean));
        const vals = {};
        if (lf) vals[lf] = frm.doc.name;
        names.forEach(fn => {
            if (fn === lf) return;
            const v = frm.doc[fn];
            if (v != null && v !== "" && frappe.meta.has_field(st.creates, fn)) vals[fn] = v;
        });
        frappe.new_doc(st.creates, vals);
    }

    function add(frm, st) {
        if (!passes(frm, st)) return;
        frappe.model.with_doctype(st.creates, async () => {
            try {
                const lf = back_link(st, frm.doctype);
                const label = __(st.button) + MARK;
                const rec = await existing(frm, st, lf);
                if (rec) {
                    frm.add_custom_button(label, () => frappe.set_route("Form", st.creates, rec), __("View"));
                } else if (st.menu === "Top Bar") {
                    frm.add_custom_button(label, () => create(frm, st, lf));
                } else {
                    frm.add_custom_button(label, () => create(frm, st, lf), __("Create"));
                }
            } catch (e) {
                console.log("Solar Create Menu: could not add " + st.button, e);
            }
        });
    }

    function hide_all(frm, list) {
        list.forEach(h => {
            try {
                if (h.menu === "Top Bar") frm.remove_custom_button(h.label);
                else frm.remove_custom_button(h.label, "Create");
            } catch (e) { /* not on the form */ }
        });
    }

    frappe.ui.form.on(DT, {
        refresh(frm) {
            frappe.call({
                method: "solar_create_menu",
                args: { doc_type: frm.doctype },
                callback: (r) => {
                    const m = r.message || {};
                    if (!frm.is_new()) (m.add || []).forEach(st => add(frm, st));
                    const hide = m.hide || [];
                    // other scripts add their buttons a moment later, so hide a few times
                    if (hide.length) [0, 300, 800, 1500, 3000].forEach(t => setTimeout(() => hide_all(frm, hide), t));
                },
            });
        },
    });
})();
