def write_sidebar(sb_name, items, keep_settings_link, sb_skipped):
    cint = frappe.utils.cint
    LINK_DOCTYPE = {"DocType": "DocType", "Workspace": "Workspace", "Report": "Report", "Page": "Page", "Dashboard": "Dashboard"}
    if not frappe.db.exists("Workspace Sidebar", sb_name):
        sb_skipped.append("sidebar '" + sb_name + "' (not on this site)")
        return
    sb = frappe.get_doc("Workspace Sidebar", sb_name)
    # settings the table does not hold (indent, keep closed, filters...) are kept from the matching current item
    EXTRA = ["indent", "keep_closed", "show_arrow", "navigate_to_tab", "filters", "route_options"]
    extras = {}
    for i in sb.items:
        extras[(i.type or "") + "|" + (i.label or "") + "|" + (i.link_to or "")] = [i.get(k) for k in EXTRA]
    rows = []
    has_settings = False
    for r in items:
        if not r.enabled:
            continue
        is_section = r.type == "Section Break"
        lt = r.link_type or "DocType"
        if not is_section:
            if lt == "URL":
                if not r.url:
                    sb_skipped.append(sb_name + " > " + (r.label or "") + " (URL is empty)")
                    continue
            else:
                if not r.link_to:
                    sb_skipped.append(sb_name + " > " + (r.label or "") + " (Link To is empty)")
                    continue
                target = LINK_DOCTYPE.get(lt)
                if target and not frappe.db.exists(target, r.link_to):
                    sb_skipped.append(sb_name + " > " + (r.label or "") + " (" + lt + " '" + r.link_to + "' not on this site)")
                    continue
        if lt == "DocType" and r.link_to == "Solar Settings":
            has_settings = True
        row = {
            "type": "Section Break" if is_section else "Link",
            "label": r.label,
            "link_type": lt,
            "link_to": None if (is_section or lt == "URL") else r.link_to,
            "url": r.url if lt == "URL" else None,
            "icon": r.icon,
            "child": 0 if is_section else cint(r.child),
            "collapsible": 1,
        }
        ex = extras.get(row["type"] + "|" + (row["label"] or "") + "|" + (row["link_to"] or ""))
        if ex:
            for n in range(len(EXTRA)):
                row[EXTRA[n]] = ex[n]
        rows.append(row)
    if keep_settings_link and not has_settings:
        rows.append({"type": "Link", "label": "Solar Settings", "link_type": "DocType", "link_to": "Solar Settings", "icon": "settings", "child": 0, "collapsible": 1})
    old = [[i.type, i.label, i.link_type, i.link_to or None, i.url or None, i.icon, cint(i.child)] for i in sb.items]
    new = [[x["type"], x["label"], x["link_type"], x["link_to"] or None, x["url"] or None, x["icon"], x["child"]] for x in rows]
    if old == new:
        return
    sb.set("items", [])
    for x in rows:
        sb.append("items", x)
    sb.save(ignore_permissions=True)


