        cf = r.customer_field or "customer"
        if not meta.has_field(cf):
            frappe.throw("Work Stages row " + str(r.idx) + " (" + r.title + "): " + r.document + " has no '" + cf + "' field to find the customer's record")
        r.customer_field = cf
        if r.status_field and not meta.has_field(r.status_field):
            frappe.throw("Work Stages row " + str(r.idx) + " (" + r.title + "): " + r.document + " has no field '" + r.status_field + "'")

# ---- Names ----
langs = ["en"]
sys_lang = frappe.db.get_single_value("System Settings", "language")
if sys_lang and sys_lang not in langs:
    langs.append(sys_lang)
want_tr = {}
for r in doc.get("custom_words") or []:
    src = (r.original or "").strip()
    dst = (r.show_as or "").strip()
    r.original = src
    r.show_as = dst
    if not src or not dst:
        frappe.throw("Names row " + str(r.idx) + ": fill both Original Text and Show As")
    for lang in langs:
        want_tr[lang + "|" + src] = {"lang": lang, "src": src, "dst": dst}

# ---- Forms: field changes ----
want = {}
entries = {}
for r in doc.get("custom_field_rules") or []:
    if not r.document or not r.fieldname:
        continue
    if not frappe.db.exists("DocType", r.document):
        skipped.append(r.document + " (document not on this site)")
        continue
    df = frappe.get_meta(r.document).get_field(r.fieldname)
    if not df:
        skipped.append(r.document + " > " + r.fieldname + " (field not on this site)")
        continue
    base = r.document + "-" + r.fieldname + "-"
    eh = original(base + "hidden", prev_ps, df.hidden)
    eq = original(base + "reqd", prev_ps, df.reqd)
    el = original(base + "label", prev_ps, df.label)
    r.orig_hidden = cint(eh.get("orig"))
    r.orig_reqd = cint(eq.get("orig"))
    r.field_label = el.get("orig") or r.fieldname
    hid = 0 if cint(r.show) else 1
    if hid != cint(eh.get("orig")):
        want[base + "hidden"] = {"dt": r.document, "field": r.fieldname, "prop": "hidden", "type": "Check", "dof": "DocField", "value": str(hid)}
        entries[base + "hidden"] = eh
    if cint(r.required) != cint(eq.get("orig")):
        want[base + "reqd"] = {"dt": r.document, "field": r.fieldname, "prop": "reqd", "type": "Check", "dof": "DocField", "value": str(cint(r.required))}
        entries[base + "reqd"] = eq
    nl = (r.new_label or "").strip()
    r.new_label = nl
    if nl and nl != el.get("orig"):
        want[base + "label"] = {"dt": r.document, "field": r.fieldname, "prop": "label", "type": "Data", "dof": "DocField", "value": nl}
        entries[base + "label"] = el

# ---- Forms: default print formats ----
seen_print = []
for r in doc.get("custom_print_defaults") or []:
    if not r.document or not r.print_format:
        continue
    if r.document in seen_print:
        frappe.throw("Default Print Formats: " + r.document + " is listed twice")
    seen_print.append(r.document)
    if not frappe.db.exists("DocType", r.document):
        skipped.append(r.document + " (document not on this site)")
        continue
    if not frappe.db.exists("Print Format", r.print_format):
        skipped.append(r.print_format + " (print format not on this site)")
        continue
    name = r.document + "-main-default_print_format"
    want[name] = {"dt": r.document, "field": None, "prop": "default_print_format", "type": "Data", "dof": "DocType", "value": r.print_format}
    entries[name] = original(name, prev_ps, frappe.get_meta(r.document).default_print_format)

# ======================= 2. APPLY =======================

# ---- Property Setters ----
new_ps = {}
for name in want:
    w = want[name]
    e = entries[name]
    new_ps[name] = {"dt": w["dt"], "field": w["field"], "prop": w["prop"], "existed": cint(e.get("existed")), "orig": as_text(e.get("orig"))}
    if frappe.db.exists("Property Setter", name):
        if as_text(frappe.db.get_value("Property Setter", name, "value")) != w["value"]:
            ps = frappe.get_doc("Property Setter", name)
            ps.value = w["value"]
            ps.save(ignore_permissions=True)
    else:
        d = {"doctype": "Property Setter", "doctype_or_field": w["dof"], "doc_type": w["dt"],
             "property": w["prop"], "property_type": w["type"], "value": w["value"],
             "default_value": "[solar-settings] " + as_text(e.get("orig"))}
        if w["field"]:
            d["field_name"] = w["field"]
        frappe.get_doc(d).insert(ignore_permissions=True)

# changes that were switched off: put the original back
# (also any change marked as made here that is no longer listed, e.g. left behind by a save that stopped halfway)
revert = {}
for name in prev_ps:
    revert[name] = prev_ps[name]
for name in frappe.get_all("Property Setter", filters={"default_value": ["like", "[solar-settings] %"]}, pluck="name"):
    if name not in revert:
        revert[name] = {"existed": 0}
for name in revert:
    if name in want:
        continue
    e = revert[name]
    if not frappe.db.exists("Property Setter", name):
        continue
    if cint(e.get("existed")):
        ps = frappe.get_doc("Property Setter", name)
        if as_text(ps.value) != as_text(e.get("orig")):
            ps.value = as_text(e.get("orig"))
            ps.save(ignore_permissions=True)
    else:
        frappe.get_doc("Property Setter", name).delete(ignore_permissions=True)

# ---- Translations ----
new_tr = {}
for k in want_tr:
    w = want_tr[k]
    tname = frappe.db.get_value("Translation", {"language": w["lang"], "source_text": w["src"]}, "name")
    if k in prev_tr:
        entry = prev_tr[k]
    elif tname and frappe.db.get_value("Translation", tname, "contribution_docname") != MARK:
        entry = {"existed": 1, "orig": frappe.db.get_value("Translation", tname, "translated_text")}
    else:
        entry = {"existed": 0, "orig": ""}
    if tname:
        if frappe.db.get_value("Translation", tname, "translated_text") != w["dst"]:
            t = frappe.get_doc("Translation", tname)
            t.translated_text = w["dst"]
            t.save(ignore_permissions=True)
    else:
        t = frappe.get_doc({"doctype": "Translation", "language": w["lang"], "source_text": w["src"],
                            "translated_text": w["dst"], "contribution_docname": MARK})
        t.insert(ignore_permissions=True)
        tname = t.name
    entry["name"] = tname
    new_tr[k] = entry

kept = []
for k in new_tr:
    kept.append(new_tr[k]["name"])
for tname in frappe.get_all("Translation", filters={"contribution_docname": MARK}, pluck="name"):
    if tname not in kept:
        prev_tr["sweep|" + tname] = {"existed": 0, "name": tname}
for k in prev_tr:
    if k in want_tr:
        continue
    e = prev_tr[k]
    tname = e.get("name")
    if tname in kept:
        continue
    if not tname or not frappe.db.exists("Translation", tname):
        continue
    if cint(e.get("existed")):
        t = frappe.get_doc("Translation", tname)
        t.translated_text = e.get("orig") or t.source_text
        t.save(ignore_permissions=True)
    else:
        frappe.get_doc("Translation", tname).delete(ignore_permissions=True)

doc.custom_applied_state = json.dumps({"ps": new_ps, "tr": new_tr}, indent=1)

if skipped:
    frappe.msgprint("These were skipped because they are not on this site:<br>" + "<br>".join(skipped), title="Solar Settings", indicator="orange")

# Server Script (API) - method: hipersign_solar_inventory
# Stock on hand per item and warehouse for the Solar "Inventory" page (same as the Fit Out Inventory view).
# Items are grouped into Low / Enough / Plenty in the browser. Reads use frappe.get_list (respects permissions).
bins = frappe.get_list("Bin", fields=["item_code", "warehouse", "actual_qty", "reserved_qty", "ordered_qty", "stock_value"],
                       limit_page_length=50000)
codes = {}
for b in bins:
    codes[b.item_code] = 1
code_list = list(codes.keys())

imeta = frappe.get_meta("Item")
ifields = ["name", "item_name", "item_group", "image", "stock_uom", "safety_stock", "modified"]
has_levels = 0
for f in ["fo_low_stock_level", "fo_plenty_stock_level"]:
    if imeta.has_field(f):
        ifields.append(f)
        has_levels = 1
items = {}
i = 0
while i < len(code_list):
    chunk = code_list[i:i + 500]
    i = i + 500
    rows = frappe.get_list("Item", filters={"name": ["in", chunk], "disabled": 0, "is_stock_item": 1},
                           fields=ifields, limit_page_length=1000)
    for r in rows:
        items[r.name] = {"code": r.name, "name": r.item_name or r.name, "group": r.item_group or "", "image": r.image or "",
                         "uom": r.stock_uom or "", "safety": float(r.safety_stock or 0), "levels": {}, "stock": [], "mod": str(r.modified or ""),
                         "low": float(r.get("fo_low_stock_level") or 0), "plenty": float(r.get("fo_plenty_stock_level") or 0)}

try:
    reorders = frappe.get_list("Item Reorder", filters={"parent": ["in", list(items.keys())]} if items else {"parent": "__none__"},
                               fields=["parent", "warehouse", "warehouse_reorder_level"], parent_doctype="Item", limit_page_length=50000)
except Exception:
    reorders = []
for r in reorders:
    if r.parent in items and r.warehouse:
        items[r.parent]["levels"][r.warehouse] = float(r.warehouse_reorder_level or 0)

used_wh = {}
for b in bins:
    it = items.get(b.item_code)
    if not it:
        continue
    it["stock"].append([b.warehouse, float(b.actual_qty or 0), float(b.reserved_qty or 0), float(b.ordered_qty or 0), float(b.stock_value or 0)])
    used_wh[b.warehouse] = 1

whs = []
if used_wh:
    for w in frappe.get_list("Warehouse", filters={"name": ["in", list(used_wh.keys())]}, fields=["name", "warehouse_name", "company"],
                             order_by="name asc", limit_page_length=5000):
        whs.append({"name": w.name, "label": w.warehouse_name or w.name, "company": w.company or ""})

out = []
for k in items:
    if items[k]["stock"]:
        out.append(items[k])

groups = {}
for x in out:
    if x["group"]:
        groups[x["group"]] = 1
glist = list(groups.keys())
glist.sort()

frappe.response["message"] = {"items": out, "warehouses": whs, "groups": glist, "default_level": 10, "plenty_factor": 3, "has_levels": has_levels}
